class SparseVector {
    vector<pair<int, int>> values;

public:
    SparseVector(vector<int>& nums) {
        for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
            if (nums[i] != 0) {
                values.push_back({i, nums[i]});
            }
        }
    }

    int dotProduct(SparseVector& vec) {
        int i = 0;
        int j = 0;
        int answer = 0;
        while (i < static_cast<int>(values.size()) &&
               j < static_cast<int>(vec.values.size())) {
            if (values[i].first == vec.values[j].first) {
                answer += values[i].second * vec.values[j].second;
                ++i;
                ++j;
            } else if (values[i].first < vec.values[j].first) {
                ++i;
            } else {
                ++j;
            }
        }
        return answer;
    }
};
